/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit } from '@angular/core';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { CourseDetailModel, ICourseDetailModel } from '../../../../../data/model/course/CourseDetailModel';
import { CourseUserVoiceViewModel, ICourseModel } from '../../../../../data/model/course/CourseModel';
import { CourseFilterModel, ICourseFilterModel } from '../../../../../data/model/course/CourseFilterModel';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { CourseService } from '../../../../../data/service/course/course.service';
import { LoadingController, ToastController, AlertController } from '@ionic/angular';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-course-media-comment',
  templateUrl: './course-media-comment.page.html',
  styleUrls: ['./course-media-comment.page.scss'],
})
export class CourseMediaCommentPage implements OnInit {

  segmentSelected = 'Add';
  searchTitle = '';
  selectedCourseId = 0;
  courseSelected = false;
  courseDetail: ICourseDetailModel;
  course: ICourseModel;
  filteredCourses: ICourseFilterModel;
  updateVideoForm: FormGroup;
  addVideoForm: FormGroup;
  selectedVideoIndex = -1;
  empty = false;

  constructor(
    private courseService: CourseService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    public alertController: AlertController,
    private router: Router) { }

  ngOnInit(): void {

    this.updateVideoForm = this.fb.group({
      comment: ['', [Validators.maxLength(1000000)]],
      buyerUserId: ['', [Validators.required, Validators.min(1)]],
      logoName: ['', [Validators.maxLength(1000000)]],
      voiceAddress: ['', [Validators.maxLength(1000000)]],
      videoAddress: ['', [Validators.maxLength(1000000)]],
      imageAddress: ['', [Validators.maxLength(1000000)]],
      userPhoto: ['', [Validators.maxLength(1000000)]],
      isActive: [false, [Validators.required]],
      isTop: [false, [Validators.required]],
      isShow: [false, [Validators.required]],
      isTeacherAnswer: [false, [Validators.required]]
    });

    this.addVideoForm = this.fb.group({
      comment: ['', [Validators.maxLength(1000000)]],
      buyerUserId: ['', [Validators.required, Validators.min(1)]],
      logoName: ['', [Validators.maxLength(1000000)]],
      voiceAddress: ['', [Validators.maxLength(1000000)]],
      videoAddress: ['', [Validators.maxLength(1000000)]],
      imageAddress: ['', [Validators.maxLength(1000000)]],
      userPhoto: ['', [Validators.maxLength(1000000)]],
      isActive: [false, [Validators.required]],
      isTop: [false, [Validators.required]],
      isShow: [false, [Validators.required]],
      isTeacherAnswer: [false, [Validators.required]]
    });

    let filter: ICourseFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter =
          new CourseFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
      } else {
        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new CourseFilterModel(false, page, take, title);
        } else {
          filter =
            new CourseFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
        }
      }
      this.filteredCourses = filter;

      SharedIonic.loading(this.loadingController);

      this.courseService.GetAdminCoursesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredCourses = res.data;
          } else {
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onSelectVideo(index: number | string): void {

    this.selectedVideoIndex = +index;

    this.updateVideoForm.setValue({
      comment: this.courseDetail.courseMediaComments[+index].comment,
      buyerUserId: this.courseDetail.courseMediaComments[+index].buyerUserId,
      logoName: this.courseDetail.courseMediaComments[+index].logoName,
      voiceAddress: this.courseDetail.courseMediaComments[+index].voiceAddress,
      videoAddress: this.courseDetail.courseMediaComments[+index].videoAddress,
      imageAddress: this.courseDetail.courseMediaComments[+index].imageAddress,
      userPhoto: this.courseDetail.courseMediaComments[+index].userPhoto,
      isActive: this.courseDetail.courseMediaComments[+index].isActive,
      isTop: this.courseDetail.courseMediaComments[+index].isTop,
      isShow: this.courseDetail.courseMediaComments[+index].isShow,
      isTeacherAnswer: this.courseDetail.courseMediaComments[+index].isTeacherAnswer
    });
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به درج هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    this.selectedVideoIndex = +index;

    SharedIonic.loading(this.loadingController);

    this.courseService.AdminDeleteUserVoice(this.courseDetail.courseMediaComments[this.selectedVideoIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.courseDetail.courseMediaComments.splice(this.selectedVideoIndex, 1);

          this.updateVideoForm.setValue({
            comment: '',
            buyerUserId: '',
            logoName: '',
            voiceAddress: '',
            videoAddress: '',
            imageAddress: '',
            userPhoto: '',
            isActive: false,
            isTop: false,
            isShow: false,
            isTeacherAnswer: false
          });
          // this.selectedCourseId = 0;
          // this.courseSelected = false;
          // this.setQueryParams(1);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.updateVideoForm.valid || this.selectedVideoIndex != -1) {

      SharedIonic.loading(this.loadingController);

      const video = new CourseUserVoiceViewModel(
        this.courseDetail.courseMediaComments[this.selectedVideoIndex].id,
        this.updateVideoForm.value.buyerUserId,
        this.selectedCourseId,
        null,
        this.updateVideoForm.value.comment,
        '',
        this.updateVideoForm.value.logoName,
        this.updateVideoForm.value.voiceAddress,
        this.updateVideoForm.value.videoAddress,
        this.updateVideoForm.value.imageAddress,
        this.updateVideoForm.value.userPhoto,
        this.updateVideoForm.value.isActive,
        this.updateVideoForm.value.isTop,
        this.updateVideoForm.value.isShow,
        this.updateVideoForm.value.isTeacherAnswer
      );

      this.courseService.AdminAddOrUpdateUserVoice(
        video
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.courseDetail.courseMediaComments[this.selectedVideoIndex].comment = this.updateVideoForm.value.comment;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].buyerUserId = this.updateVideoForm.value.buyerUserId;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].logoName = this.updateVideoForm.value.logoName;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].voiceAddress = this.updateVideoForm.value.voiceAddress;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].videoAddress = this.updateVideoForm.value.videoAddress;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].imageAddress = this.updateVideoForm.value.imageAddress;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].userPhoto = this.updateVideoForm.value.userPhoto;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].isActive = this.updateVideoForm.value.isActive;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].isTop = this.updateVideoForm.value.isTop;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].isShow = this.updateVideoForm.value.isShow;
            this.courseDetail.courseMediaComments[this.selectedVideoIndex].isTeacherAnswer = this.updateVideoForm.value.isTeacherAnswer;

            this.updateVideoForm.setValue({
              comment: '',
              buyerUserId: '',
              logoName: '',
              voiceAddress: '',
              videoAddress: '',
              imageAddress: '',
              userPhoto: '',
              isActive: false,
              isTop: false,
              isShow: false,
              isTeacherAnswer: false
            });
            this.selectedVideoIndex = -1;
            // this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addVideoForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.courseService.AdminAddOrUpdateUserVoice(
        new CourseUserVoiceViewModel(
          0,
          this.addVideoForm.value.buyerUserId,
          this.selectedCourseId,
          null,
          this.addVideoForm.value.comment,
          '',
          this.addVideoForm.value.logoName,
          this.addVideoForm.value.voiceAddress,
          this.addVideoForm.value.videoAddress,
          this.addVideoForm.value.imageAddress,
          this.addVideoForm.value.userPhoto,
          this.addVideoForm.value.isActive,
          this.addVideoForm.value.isTop,
          this.addVideoForm.value.isShow,
          this.addVideoForm.value.isTeacherAnswer
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addVideoForm.setValue({
              comment: '',
              buyerUserId: '',
              logoName: '',
              voiceAddress: '',
              videoAddress: '',
              imageAddress: '',
              userPhoto: '',
              isActive: false,
              isTop: false,
              isShow: false,
              isTeacherAnswer: false
            });
            this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredCourses.title = this.searchTitle;

    this.router
      .navigate(
        ['SuperAdminPanel', 'CourseMediaComment'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null,
            startPrice: this.filteredCourses.startPrice ? this.filteredCourses.startPrice : null,
            endPrice: this.filteredCourses.endPrice ? this.filteredCourses.endPrice : null,
            categoryIds: this.filteredCourses.categoryIds ? this.filteredCourses.categoryIds : [],
            sortId: this.filteredCourses.sortId ? this.filteredCourses.sortId : 0
          }
        });
  }

  onSelectItem(model: ICourseModel) {

    this.selectedCourseId = +model.id;
    this.course = model;

    // tslint:disable-next-line: max-line-length
    this.courseDetail = new CourseDetailModel(this.selectedCourseId, model.name, model.price, model.offPrice, 0, model.shortDescription, model.description, model.imageUrl, '', '', model.createDate, model.lastUpdateDate, [], [], [], false, model.teacher, false, model.isActive, '', '', '', 100);

    SharedIonic.loading(this.loadingController);

    this.courseService.GetAdminCourseUserVoices(this.selectedCourseId).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          const video = [];

          res.data.forEach(v => {
            video.push(
              // tslint:disable-next-line: max-line-length
              new CourseUserVoiceViewModel(v.id, v.buyerUserId, v.courseId, v.parentId, v.comment, v.userName, v.logoName, v.voiceAddress, v.videoAddress, v.imageAddress, v.userPhoto, v.isActive, v.isTop, v.isShow, v.isTeacherAnswer)
            );
          });

          this.courseDetail.courseMediaComments = video;
          this.updateVideoForm.setValue({
            comment: '',
            buyerUserId: '',
            logoName: '',
            voiceAddress: '',
            videoAddress: '',
            imageAddress: '',
            userPhoto: '',
            isActive: false,
            isTop: false,
            isShow: false,
            isTeacherAnswer: false
          });
          this.courseSelected = true;
        } else {
          this.courseDetail.courseVideos = [];
          this.selectedCourseId = 0;
          this.courseSelected = false;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        this.courseDetail.courseVideos = [];
        this.selectedCourseId = 0;
        this.courseSelected = false;
      }
    );
  }

  onCancel() {

    this.selectedCourseId = 0;
    this.courseSelected = false;
  }
}
